def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def fibonacci_sequence():
        a, b = 0, 1
        while True:
            a, b = b, a + b
            yield a

    count = 0
    for num in fibonacci_sequence():
        if is_prime(num):
            count += 1
            if count == n:
                return num

