    counts = {}
    for char in test.split():
        counts[char] = counts.get(char, 0) + 1

    if not counts:
        return {}

    max_count = max(counts.values())
    result = {}
    for char, count in counts.items():
        if count == max_count:
            result[char] = count

    return result
